function Finance({ finance, onAdd, onDelete }) {
  const income = finance.filter(f => f.type === "income").reduce((s, f) => s + f.amount, 0);
  const expense = finance.filter(f => f.type === "expense").reduce((s, f) => s + f.amount, 0);
  return (
    <div>
      <div className="flex justify-between items-center mb-5">
        <h1 className="text-xl font-bold text-emerald-900">Finance Tracker</h1>
        <button onClick={onAdd} className="bg-emerald-700 text-white text-sm px-3 py-2 rounded-lg flex items-center gap-1.5"><Plus size={14} /> Add Entry</button>
      </div>
      <div className="grid grid-cols-2 md:grid-cols-3 gap-3 md:gap-4 mb-5">
        <StatCard num={`₱${income}`} label="Total Income" />
        <StatCard num={`₱${expense}`} label="Total Expense" />
        <StatCard num={`₱${income - expense}`} label="Balance" />
      </div>
      <div className="bg-white rounded-xl border border-stone-200 overflow-x-auto">
        <table className="w-full text-sm min-w-[500px]">
          <thead><tr className="bg-emerald-50 text-emerald-900 text-left"><th className="p-3">Type</th><th className="p-3">Category</th><th className="p-3">Amount</th><th className="p-3">Date</th><th className="p-3"></th></tr></thead>
          <tbody>{finance.map(f => (
            <tr key={f.id} className="border-t border-stone-100">
              <td className="p-3"><Badge tone={f.type === "income" ? "active" : "inactive"}>{f.type}</Badge></td>
              <td className="p-3">{f.category}</td><td className="p-3">₱{f.amount}</td><td className="p-3 text-stone-500">{f.date}</td>
              <td className="p-3"><button onClick={() => onDelete(f.id)} className="text-rose-600"><Trash2 size={14} /></button></td>
            </tr>
          ))}</tbody>
        </table>
      </div>
    </div>
  );
}

function UserManagement({ users, onAdd, onToggle, onDelete, onEditAccess }) {
  const [visiblePw, setVisiblePw] = useState({});
  const togglePw = (id) => setVisiblePw(v => ({ ...v, [id]: !v[id] }));

  return (
    <div>
      <div className="flex justify-between items-center mb-5">
        <h1 className="text-xl font-bold text-emerald-900">User Management</h1>
        <button onClick={onAdd} className="bg-emerald-700 text-white text-sm px-3 py-2 rounded-lg flex items-center gap-1.5"><Plus size={14} /> Create User</button>
      </div>
      <div className="bg-white rounded-xl border border-stone-200 overflow-x-auto">
        <table className="w-full text-sm min-w-[680px]">
          <thead><tr className="bg-emerald-50 text-emerald-900 text-left"><th className="p-3">Name</th><th className="p-3">Username</th><th className="p-3">Password</th><th className="p-3">Role</th><th className="p-3">Status</th><th className="p-3"></th></tr></thead>
          <tbody>{users.map(u => (
            <tr key={u.id} className="border-t border-stone-100">
              <td className="p-3">{u.name}</td>
              <td className="p-3 text-stone-500">{u.username}</td>
              <td className="p-3 text-stone-500">
                <div className="flex items-center gap-1.5">
                  <span className="font-mono">{visiblePw[u.id] ? u.password : "••••••••"}</span>
                  <button onClick={() => togglePw(u.id)} className="text-stone-400 hover:text-emerald-700">
                    {visiblePw[u.id] ? <EyeOff size={13} /> : <Eye size={13} />}
                  </button>
                </div>
              </td>
              <td className="p-3">{u.role}</td>
              <td className="p-3"><Badge tone={u.active ? "active" : "inactive"}>{u.active ? "Active" : "Inactive"}</Badge></td>
              <td className="p-3 space-x-2 whitespace-nowrap">
                {u.role !== "superadmin" ? <>
                  <button onClick={() => onEditAccess(u)} className="text-emerald-700 text-xs font-medium">Edit</button>
                  <button onClick={() => onToggle(u.id)} className="text-emerald-700 text-xs">{u.active ? "Deactivate" : "Activate"}</button>
                  <button onClick={() => onDelete(u.id)} className="text-rose-600 text-xs">Delete</button>
                </> : <button onClick={() => onEditAccess(u)} className="text-emerald-700 text-xs font-medium">Edit</button>}
              </td>
            </tr>
          ))}</tbody>
        </table>
      </div>
    </div>
  );
}

const FLAGGED_WORDS = ["bobo", "gago", "tanga", "putangina", "ulol"]; // basic placeholder filter — expand as needed

function Suggestions({ isGuest, suggestions, onSubmit, onDelete }) {
  const [msg, setMsg] = useState("");
  const [sent, setSent] = useState(false);
  const [error, setError] = useState("");
  const [showPolicy, setShowPolicy] = useState(false);

  function handleSend() {
    const trimmed = msg.trim();
    if (!trimmed) return;
    const lower = trimmed.toLowerCase();
    const hasFlagged = FLAGGED_WORDS.some(w => lower.includes(w));
    if (hasFlagged) {
      setError("Hindi mai-send ang message mo — may laman itong salitang labag sa Policy of Use. Paki-ayos at subukan ulit.");
      return;
    }
    onSubmit(trimmed);
    setMsg("");
    setError("");
    setSent(true);
    setTimeout(() => setSent(false), 2500);
  }

  if (isGuest) {
    return (
      <div>
        <h1 className="text-xl font-bold text-emerald-900 mb-2">Suggestions / Feedback</h1>
        <p className="text-sm text-stone-500 mb-3">May gusto ka bang iparating sa mga officers? Ipadala mo lang dito — mababasa lang ito ng Super Admin at President.</p>
        <button onClick={() => setShowPolicy(true)} className="text-xs text-emerald-700 underline mb-4 block">📋 View Policy of Use</button>
        <div className="bg-white rounded-xl border border-stone-200 p-5 max-w-lg">
          {sent && <div className="bg-emerald-50 text-emerald-700 text-sm rounded-lg p-2.5 mb-3">Salamat! Naipadala na ang suggestion mo.</div>}
          {error && <div className="bg-rose-50 text-rose-700 text-sm rounded-lg p-2.5 mb-3">{error}</div>}
          <textarea className={inputCls} rows={4} placeholder="Isulat ang iyong suggestion o feedback..." value={msg} onChange={e => setMsg(e.target.value)} />
          <p className="text-[11px] text-stone-400 mt-2">Sa pag-send, sumasang-ayon ka sa aming Policy of Use — bawal ang bastos, mapanira, o hindi kaaya-ayang nilalaman.</p>
          <button
            onClick={handleSend}
            className="mt-3 bg-emerald-700 text-white text-sm px-4 py-2 rounded-lg"
          >
            Send Suggestion
          </button>
        </div>
        {showPolicy && <PolicyModal onClose={() => setShowPolicy(false)} />}
      </div>
    );
  }

  return (
    <div>
      <h1 className="text-xl font-bold text-emerald-900 mb-2">Suggestions Inbox</h1>
      <p className="text-sm text-stone-500 mb-5">Visible lang sa Super Admin at President. Mga natanggap na suggestion/feedback mula sa Guest Mode.</p>
      {suggestions.length === 0 ? (
        <p className="text-sm text-stone-400">Wala pang natatanggap na suggestion.</p>
      ) : (
        suggestions.map(s => (
          <div key={s.id} className="bg-white rounded-xl border border-stone-200 p-4 mb-3 flex justify-between items-start">
            <div>
              <div className="text-[11px] text-stone-400 mb-1">{s.date} • Anonymous (Guest)</div>
              <p className="text-sm text-stone-700">{s.message}</p>
            </div>
            <button onClick={() => onDelete(s.id)} className="text-rose-600 flex-shrink-0 ml-3"><Trash2 size={14} /></button>
          </div>
        ))
      )}
    </div>
  );
}

